CREATE FUNCTION public.fn_folha_plano_integrado_v3(p_dados jsonb,p_confirmar boolean DEFAULT false,p_versao text DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $plan$
DECLARE u public.utilizadores;p uuid:=(p_dados->>'person_id')::uuid;d date:=(p_dados->>'date')::date;k text:=p_dados->>'kind';w uuid:=(p_dados->>'work_id')::uuid;req uuid:=(p_dados->>'request_id')::uuid;sites jsonb:=p_dados->'sites';s jsonb;xs jsonb;unchanged jsonb;source jsonb;ev jsonb;ref public.folha_referencias;body jsonb;pre jsonb;preview jsonb:='[]';payload jsonb;token text;result jsonb;results jsonb:='[]';op folha_privado.operacoes;rev integer;count_unchanged integer;day_summary jsonb;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'RETRY_READ_COMMITTED' USING ERRCODE='40001';END IF;
 LOCK TABLE public.quadro_pessoal_alocacao IN ROW EXCLUSIVE MODE;PERFORM pg_advisory_xact_lock(61001,1);u:=folha_privado.ator();PERFORM 1 FROM public.utilizadores WHERE id=u.id FOR SHARE;u:=folha_privado.ator();IF (p_dados ? 'empresa_id' AND (p_dados->>'empresa_id')::uuid IS DISTINCT FROM u.empresa_id) OR (p_dados ? 'company_id' AND (p_dados->>'company_id')::uuid IS DISTINCT FROM u.empresa_id) THEN RAISE EXCEPTION 'TENANT_HINT_MISMATCH' USING ERRCODE='42501';END IF;PERFORM folha_privado.destino_autorizar_v3(p,w,k,true);PERFORM folha_privado.lock_dia(p,d);
 IF req IS NULL OR p IS NULL OR d IS NULL OR k IS NULL OR k NOT IN('primeline','external') OR p_confirmar IS NULL OR (p_dados->>'version')::integer IS DISTINCT FROM 3 OR jsonb_typeof(sites) IS DISTINCT FROM 'array' OR jsonb_array_length(sites) NOT BETWEEN 1 AND 4 OR EXISTS(SELECT 1 FROM jsonb_array_elements(sites) x WHERE x->>'type' IS NULL OR x->>'type' NOT IN('obra','reference') OR jsonb_typeof(x->'intervals') IS DISTINCT FROM 'array' OR jsonb_array_length(x->'intervals') NOT BETWEEN 1 AND 16) OR EXISTS(SELECT 1 FROM jsonb_array_elements(sites) x GROUP BY x->>'type',CASE WHEN x->>'type'='obra' THEN x->>'work_id' ELSE x->>'id' END HAVING count(*)>1) THEN RAISE EXCEPTION 'PLAN_INVALID';END IF;
 IF k='primeline' THEN PERFORM 1 FROM public.colaboradores WHERE id=p AND empresa_id=u.empresa_id AND data_admissao<=d AND (data_saida IS NULL OR data_saida>d) FOR UPDATE;ELSE PERFORM 1 FROM public.folha_externos e JOIN public.fornecedores provider ON provider.id=e.fornecedor_id WHERE e.id=p AND e.empresa_id=u.empresa_id AND provider.empresa_id=u.empresa_id AND (e.ativo OR (folha_privado.adm_operacional() OR u.funcao='diretor_obra') AND EXISTS(SELECT 1 FROM public.folha_registos existing WHERE existing.externo_id=p AND existing.data=d AND existing.empresa_id=u.empresa_id)) FOR UPDATE OF e;END IF;IF NOT FOUND THEN RAISE EXCEPTION 'PERMISSION_DENIED: pessoa' USING ERRCODE='42501';END IF;
 FOR s IN SELECT value FROM jsonb_array_elements(sites) ORDER BY value->>'type',coalesce(value->>'work_id',value->>'id') LOOP
  IF s->>'type'='obra' THEN IF s->>'work_id' IS NULL THEN RAISE EXCEPTION 'DESTINATION_REQUIRED';END IF;PERFORM folha_privado.destino_autorizar_v3(p,(s->>'work_id')::uuid,k,true);
  ELSE IF s->>'id' IS NULL THEN RAISE EXCEPTION 'REFERENCE_REQUIRED';END IF;PERFORM folha_privado.destino_autorizar_v3(p,(s->>'origin_work_id')::uuid,k,true);SELECT * INTO ref FROM public.folha_referencias WHERE id=(s->>'id')::uuid FOR UPDATE;IF ref.id IS NOT NULL AND (ref.empresa_id<>u.empresa_id OR ref.data<>d OR coalesce(ref.colaborador_id,ref.externo_id)<>p OR (ref.colaborador_id IS NULL)<>(k='external')) THEN RAISE EXCEPTION 'PERMISSION_DENIED: referência' USING ERRCODE='42501';END IF;END IF;
 END LOOP;
 payload:=jsonb_build_object('action','integrated_plan','data',p_dados);SELECT * INTO op FROM folha_privado.operacoes WHERE empresa_id=u.empresa_id AND ator_id=u.id AND request_id=req;
 IF FOUND THEN IF op.payload IS DISTINCT FROM payload THEN RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT';END IF;IF NOT p_confirmar THEN RETURN jsonb_build_object('version',3,'committed',false,'versao',op.token);END IF;IF p_versao IS DISTINCT FROM op.token THEN RAISE EXCEPTION 'STALE_PREVIEW' USING ERRCODE='40001';END IF;RETURN op.resultado;END IF;
 IF k='primeline' THEN SELECT to_jsonb(a) INTO ev FROM public.folha_avaliacoes_diarias a WHERE colaborador_id=p AND data=d AND empresa_id=u.empresa_id FOR UPDATE;IF (p_dados->>'expected_daily_revision')::integer IS DISTINCT FROM coalesce((ev->>'revision')::integer,0) THEN RAISE EXCEPTION 'STALE_REVISION: diária' USING ERRCODE='40001';END IF;END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]') INTO source FROM (SELECT to_jsonb(f) value FROM public.folha_registos f WHERE f.data=d AND CASE WHEN k='primeline' THEN f.colaborador_id=p ELSE f.externo_id=p END UNION ALL SELECT to_jsonb(r) value FROM public.folha_referencias r WHERE r.data=d AND CASE WHEN k='primeline' THEN r.colaborador_id=p ELSE r.externo_id=p END) x;
 SELECT coalesce(jsonb_agg(x),'[]') INTO unchanged FROM (SELECT x FROM public.folha_registos f CROSS JOIN LATERAL jsonb_array_elements(f.intervals) x WHERE f.data=d AND CASE WHEN k='primeline' THEN f.colaborador_id=p ELSE f.externo_id=p END AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(sites) target WHERE target->>'type'='obra' AND (target->>'work_id')::uuid IS NOT DISTINCT FROM f.obra_id) UNION ALL SELECT x FROM public.folha_referencias r CROSS JOIN LATERAL jsonb_array_elements(r.intervals) x WHERE r.data=d AND CASE WHEN k='primeline' THEN r.colaborador_id=p ELSE r.externo_id=p END AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(sites) target WHERE target->>'type'='reference' AND (target->>'id')::uuid=r.id)) q;
 SELECT coalesce(jsonb_agg(x),'[]') INTO xs FROM jsonb_array_elements(sites) target CROSS JOIN LATERAL jsonb_array_elements(target->'intervals') x;
 xs:=xs||unchanged;IF jsonb_array_length(xs)>16 THEN RAISE EXCEPTION 'INTERVAL_LIMIT';END IF;PERFORM folha_privado.facts(xs,d);
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(sites) target CROSS JOIN LATERAL jsonb_array_elements(target->'intervals') x WHERE x ? 'daily_scope' OR x->>'mode' IS NULL OR x->>'mode' NOT IN('normal','personalizado') OR x->>'mode'='personalizado' AND x->>'period' IS NOT NULL OR x->>'mode'='normal' AND coalesce(x->>'period','') NOT IN('manha','tarde')) THEN RAISE EXCEPTION 'PERIOD_REQUIRED';END IF;
 SELECT count(*) INTO count_unchanged FROM (SELECT f.id FROM public.folha_registos f WHERE f.data=d AND CASE WHEN k='primeline' THEN f.colaborador_id=p ELSE f.externo_id=p END AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(sites) target WHERE target->>'type'='obra' AND (target->>'work_id')::uuid IS NOT DISTINCT FROM f.obra_id) UNION ALL SELECT r.id FROM public.folha_referencias r WHERE r.data=d AND CASE WHEN k='primeline' THEN r.colaborador_id=p ELSE r.externo_id=p END AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(sites) target WHERE target->>'type'='reference' AND (target->>'id')::uuid=r.id)) q;IF count_unchanged+jsonb_array_length(sites)>4 THEN RAISE EXCEPTION 'DESTINATION_LIMIT';END IF;
 FOR s IN SELECT value FROM jsonb_array_elements(sites) ORDER BY value->>'type',coalesce(value->>'work_id',value->>'id') LOOP
  IF s->>'type'='obra' THEN
   IF EXISTS(SELECT 1 FROM public.obras WHERE id=(s->>'work_id')::uuid AND situacao<>'em_curso') AND NOT EXISTS(SELECT 1 FROM public.folha_registos f WHERE f.obra_id=(s->>'work_id')::uuid AND f.data=d AND CASE WHEN k='primeline' THEN f.colaborador_id=p ELSE f.externo_id=p END) THEN RAISE EXCEPTION 'DESTINATION_NOT_ACTIVE';END IF;
   body:=jsonb_build_object('key',jsonb_build_object('kind',k,'person_id',p,'date',d,'work_id',s->>'work_id'),'expected_revision',s->'expected_revision','intervals',CASE WHEN k='primeline' THEN (SELECT jsonb_agg(x||jsonb_build_object('daily_scope',true) ORDER BY n) FROM jsonb_array_elements(s->'intervals') WITH ORDINALITY t(x,n)) ELSE s->'intervals' END,'reason',p_dados->>'reason','note',p_dados->>'note');pre:=folha_privado.save_plano_integrado_v3(body,(s->>'work_id')::uuid,d,req,false,sites);
  ELSE
   body:=jsonb_build_object('version',3,'request_id',md5(req::text||':'||(s->>'id'))::uuid,'id',s->>'id','kind',k,'person_id',p,'date',d,'origin_work_id',s->>'origin_work_id','type',s->>'reference_type','original_reference',s->>'original_reference','original_work_id',s->>'original_work_id','expected_revision',s->'expected_revision','expected_daily_revision',p_dados->'expected_daily_revision','intervals',s->'intervals','reason',p_dados->>'reason');pre:=folha_privado.referencia_plano_integrado_v3('save_reference',body,false,NULL,sites);
  END IF;preview:=preview||jsonb_build_array(jsonb_build_object('type',s->>'type','identity',coalesce(s->>'work_id',s->>'id'),'data',CASE WHEN s->>'type'='reference' THEN jsonb_build_object('versao',pre->>'versao') ELSE pre END));
 END LOOP;
 token:=encode(sha256(convert_to(jsonb_build_object('actor',u.id,'tenant',u.empresa_id,'payload',payload,'source',source,'daily',ev,'reference',CASE WHEN k='primeline' AND ev IS NULL THEN folha_privado.diaria_referencia(p,d) END,'previews',preview)::text,'UTF8')),'hex');IF NOT p_confirmar THEN RETURN jsonb_build_object('version',3,'committed',false,'versao',token,'targets',jsonb_array_length(sites),'minutes',(folha_privado.facts(xs,d)->>'minutes')::integer);END IF;IF p_versao IS DISTINCT FROM token THEN RAISE EXCEPTION 'STALE_PREVIEW' USING ERRCODE='40001';END IF;
 FOR s IN SELECT value FROM jsonb_array_elements(sites) ORDER BY value->>'type',coalesce(value->>'work_id',value->>'id') LOOP
  IF s->>'type'='obra' THEN body:=jsonb_build_object('key',jsonb_build_object('kind',k,'person_id',p,'date',d,'work_id',s->>'work_id'),'expected_revision',s->'expected_revision','intervals',CASE WHEN k='primeline' THEN (SELECT jsonb_agg(x||jsonb_build_object('daily_scope',true) ORDER BY n) FROM jsonb_array_elements(s->'intervals') WITH ORDINALITY t(x,n)) ELSE s->'intervals' END,'reason',p_dados->>'reason','note',p_dados->>'note');result:=folha_privado.save_plano_integrado_v3(body,(s->>'work_id')::uuid,d,req,true,sites);results:=results||jsonb_build_array(jsonb_build_object('type','obra','record',result->'result'));
  ELSE IF k='primeline' THEN SELECT coalesce((SELECT revision FROM public.folha_avaliacoes_diarias WHERE colaborador_id=p AND data=d),0) INTO rev;END IF;
   body:=jsonb_build_object('version',3,'request_id',md5(req::text||':'||(s->>'id'))::uuid,'id',s->>'id','kind',k,'person_id',p,'date',d,'origin_work_id',s->>'origin_work_id','type',s->>'reference_type','original_reference',s->>'original_reference','original_work_id',s->>'original_work_id','expected_revision',s->'expected_revision','expected_daily_revision',rev,'intervals',s->'intervals','reason',p_dados->>'reason');pre:=folha_privado.referencia_plano_integrado_v3('save_reference',body,false,NULL,sites);result:=folha_privado.referencia_plano_integrado_v3('save_reference',body,true,pre->>'versao',sites);results:=results||jsonb_build_array(jsonb_build_object('type','reference','reference',result->'reference'));
  END IF;
 END LOOP;
 IF k='primeline' THEN result:=folha_privado.diaria_recalcular(p,d,req);day_summary:=jsonb_build_object('revision',result->'revision','mode',result->'modo_dia','state',result->'estado','minutes',result->'realizado_minutes','expected_minutes',result->'expected_minutes','reference_state',result->'referencia_estado','he_state',result->'he_estado','pending',result->'pendencias');END IF;
 result:=jsonb_build_object('version',3,'committed',true,'request_id',req,'results',results,'daily_summary',day_summary);INSERT INTO folha_privado.operacoes VALUES(u.empresa_id,u.id,req,payload,token,result,now());RETURN result;
END $plan$;
